var seed = Math.random() * 1000;
var mySize;
let tile_count = 20;
let colorsME = "ff2800-ff1200".split("-").map((a) => "#" + a);
let colorsME2 = "ff280000-ff120000".split("-").map((a) => "#" + a);
let colors1 = "004840-34645c-20302d".split("-").map((a) => "#" + a);
let colors2 = "00484000-34645c00-20302d00".split("-").map((a) => "#" + a);
let colors3 = "583f99-917bbb-3c2c64".split("-").map((a) => "#" + a);
let colors4 = "583f9900-917bbb00-3c2c6400".split("-").map((a) => "#" + a);
let colors5 = "3c2777-2b1d4f-5e478d".split("-").map((a) => "#" + a);
let colors6 = "3c277700-2b1d4f00-5e478d00".split("-").map((a) => "#" + a);
var UrbanBuildings;

function setup() {
	pixelDensity(2);
	createCanvas(1112, 834);
	mySize = width;
	randomSeed(seed);
	background(10);
	addUB();
}

function draw() {
	randomSeed(seed);
	background(10);
	for (let UB of UrbanBuildings) {
		UB.display();
	}
	noLoop();
}

function addUB() {
	UrbanBuildings = [];
	let w = mySize / tile_count;
	for (let i = 0; i < tile_count; i++) {
		for (let j = 0; j < tile_count; j++) {
			//colorItem [i][j] = i*j;
			let noiseW = random(-10, 10);
			let noiseH = random(-10, 10);
			let x = i * w + noiseW;
			let y = j * w + noiseH;
			let colorItem = int(random(3));
			let ME_index = 100;
			if (i * j == ME_index) {
				UrbanBuildings.push(
					new ME(x, y, w, random(colorsME), random(colorsME2))
				);
			} else if (colorItem == 0 && i * j != ME_index) {
				UrbanBuildings.push(
					new UrbanBuilding(x, y, w, random(colors1), random(colors2))
				);
			} else if (colorItem == 1 && i * j != ME_index) {
				UrbanBuildings.push(
					new UrbanBuilding(x, y, w, random(colors3), random(colors4))
				);
			} else if (colorItem == 2 && i * j != ME_index) {
				UrbanBuildings.push(
					new UrbanBuilding(x, y, w, random(colors5), random(colors6))
				);
			}
		}
	}
}

// make UrbanBuilding by position
class UrbanBuilding {
	constructor(x, y, w, color1, color2) {
		this.x = x;
		this.y = y - 50;
		this.w = w * random(2);
		this.h = random(2, 4) * this.w;
		this.strWei = random(1, 4);
		this.color1 = color1;
		this.color2 = color2;
	}
	display() {
		push();
		translate(this.x + this.w / 2, this.y + this.w / 2);
		this.grad = drawingContext.createLinearGradient(0, 0, 0, this.h);
		this.grad.addColorStop(0, this.color1);
		this.grad.addColorStop(0.75, this.color2);
		drawingContext.strokeStyle = this.grad;
		fill("#ffffff00");
		let lineNum = this.w / this.strWei;
		let space = this.w / lineNum;
		for (let i = 1; i < lineNum; i++) {
			strokeCap(SQUARE);
			strokeWeight(random(space / 4, space / 2));
			line(
				-this.w / 2 + i * space,
				0,
				-this.w / 2 + i * space,
				random(this.h / 2, this.h)
			);
		}
		strokeCap(SQUARE);
		strokeWeight(this.strWei);
		rect(-this.w / 2, 0, this.w, this.h);

		pop();
	}
}

// make ME by position
class ME {
	constructor(x, y, w, color1, color2) {
		this.x = x - random(width / 15, width / 8);
		this.y = y - random(height / 12, height / 6);
		this.w = w * random(0.5, 3);
		this.h = random(1, 3) * this.w;
		this.strWei = this.w * random(0.05, 0.15);
		this.color1 = color1;
		this.color2 = color2;
		this.colorbg1 = color("#00000080");
		this.colorbg2 = color("#00000000");
	}
	display() {
		push();
		translate(this.x + this.w / 2, this.y + this.w / 2);
		this.gradbg = drawingContext.createLinearGradient(0, 0, 0, this.h);
		this.gradbg.addColorStop(0, this.colorbg1);
		this.gradbg.addColorStop(1, this.colorbg2);
		drawingContext.strokeStyle = this.gradbg;
		noFill();
		//stroke(this.gradbg);
		strokeCap(SQUARE);
		strokeWeight(this.w);
		line(0, 0, 0, this.h);

		this.grad = drawingContext.createLinearGradient(0, 0, 0, this.h);
		this.grad.addColorStop(0, this.color1);
		this.grad.addColorStop(1, this.color2);
		drawingContext.strokeStyle = this.grad;
		noFill();
		strokeCap(SQUARE);
		strokeWeight(this.strWei);
		drawingContext.shadowColor = color(0, 0, 0, 90);
		drawingContext.shadowOffsetX = 20;
		drawingContext.shadowOffsetY = 20;
		drawingContext.shadowBlur = 20;
		//rect(-this.w / 2, 0, this.w, this.h);
		drawingContext.shadowColor = color(0, 0, 0, 0);
		//line(-this.w / 2, 0, this.w / 2, this.h / 4);
		//line(this.w / 2, 0, 0, this.h / 8);
		pop();
	}
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  // prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  }
}

